{"name":"SetAirPurifierHighModeIfCO2Above1200PPMAndPersonDetected","cron":"","period":0,"code":"co2_level = (#AirQualitySensor).airqualitysensor_carbondioxide
person_detected = (#PresenceSensor).presencesensor_presence
if (co2_level >= 1200 and person_detected == true) {
    (#AirPurifier).airpurifier_setdehumidifiermode("auto")
    (#Speaker).speaker_speak("공기청정기가 강풍 모드로 변경되었습니다.")
}"}

{"name":"DehumidifierSetDryingMode","cron":"","period":0,"code":"if ((#RainSensor).rainsensor_rain == true) {
    (#Dehumidifier).dehumidifier_setdehumidifiermode("drying")
    delay(1 HOUR)
    if ((#WeatherProvider).weatherprovider_weather != "rain") {
        (#Dehumidifier).dehumidifier_setdehumidifiermode("auto")
    }
}
(#Speaker).speaker_speak("제습기가 건조 모드로 작동 중입니다")"}

{"name":"AdjustAirConditionerBasedOnTemperature","cron":"","period":0,"code":"prev_temp := (#AirQualitySensor).airqualitysensor_temperature
curr_temp := (#AirQualitySensor).airqualitysensor_temperature
if (prev_temp >= 20 and curr_temp < 20) {
    (#AirConditioner).airconditioner_setairconditionermode("auto")
} else if (prev_temp < 20 and curr_temp >= 20) {
    (#AirConditioner).airconditioner_setairconditionermode("cool")
}
prev_temp = curr_temp"}

{"name":"RepeatDoorOpeningEveryHour","cron":"","period":3600000,"code":"prev := (#Door).door_doorstate
curr = (#Door).door_doorstate
if (prev == false and curr == true) {
    (#Door).door_open()
    delay(1 HOUR)
    (#Door).door_close()
}
prev = curr"}

